-- =====================================================================
-- CSMJU2030 master data — ข้อมูลตั้งต้นทั้งหมด (สคริปต์เดียว รันซ้ำได้)
--
-- ที่มา: เว็บสาขา gates.csmju.com (ดึง 25 ก.ย. 2569) · reg.mju.ac.th · edu.mju.ac.th
--        · รายชื่อนักศึกษารุ่น 67 และอาจารย์ที่ปรึกษา
-- รัน:   cd backend
--        pnpm prisma migrate deploy
--        pnpm build && pnpm prisma db seed
--        pnpm prisma db execute --file prisma/data/master-data.sql
-- ทุกคำสั่งเป็น upsert — รันซ้ำไม่เกิดข้อมูลซ้ำ และไม่แตะการผูกบัญชี (core_user_id)
-- =====================================================================

-- ===== คณะ / สาขา =====
INSERT INTO faculties (id,code,name_th,name_en) VALUES (gen_random_uuid()::text,'SCI','คณะวิทยาศาสตร์','Faculty of Science') ON CONFLICT (code) DO UPDATE SET name_th=EXCLUDED.name_th, name_en=EXCLUDED.name_en, updated_at=now();
INSERT INTO departments (id,code,faculty_id,name_th,name_en) VALUES (gen_random_uuid()::text,'CS',(SELECT id FROM faculties WHERE code='SCI'),'สาขาวิชาวิทยาการคอมพิวเตอร์','Computer Science') ON CONFLICT (code) DO UPDATE SET faculty_id=EXCLUDED.faculty_id, name_th=EXCLUDED.name_th, name_en=EXCLUDED.name_en, updated_at=now();

-- ===== หลักสูตรที่รุ่น 67 ใช้ (รายละเอียดเต็มอยู่ในส่วนข้อมูลเว็บด้านล่าง) =====
