INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'บทนำ',NULL,'สาขาวิชาวิทยาการคอมพิวเตอร์ ได้ดำเนินการเปิดสอนมาตั้งแต่ปีการศึกษา2536 เป็นสาขาวิชาแรกของคณะวิทยาศาสตร์ที่เริ่มจัดตั้งมาพร้อมกับคณะวิทยาศาสตร์ โดยมีประวัติความเป็นมาดังนี้',1)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2536',2536,'หมวดวิชาวิทยาศาสตร์และคณิตศาสตร์ ภาควิชาศึกษาทั่วไป คณะธุรกิจการเกษตร ได้แยกตัวออกมาเพื่อจัดตั้งเป็นคณะวิทยาศาสตร์ โดยมีภาควิชาวิทยาการคอมพิวเตอร์เป็นภาควิชาหนึ่งที่สังกัดในคณะวิทยาศาสตร์ ในระยะเริ่มแรกได้บริหารจัดการโดย หัวหน้าภาควิชาคนแรก (รองศาสตราจารย์จรัส กาใหญ่) ต่อมาได้ขยายจำนวนรับคณาจารย์มากขึ้นตามลำดับ โดยมีภาระงานสอนรายวิชาคอมพิวเตอร์เบื้องต้น ซึ่งเป็นรายวิชาพื้นฐานสำหรับนักศึกษาในหลายสาขาวิชา นอกจากนั้นยังเปิดสอนรายวิชาการเขียนโปรแกรมภาษาเบสิค และรายวิชาโปรแกรมสำเร็จรูปเพื่อเป็นวิชาเลือกให้กับนักศึกษาที่สนใจเรียนรายวิชาทางด้านคอมพิวเตอร์เป็นวิชาเลือกเสรีอีกด้วย ขณะนั้นใช้เครื่องไมโครคอมพิวเตอร์รุ่น 386 จำนวน 30 เครื่อง เป็นอุปกรณ์ที่ใช้ในการเรียนการสอน โดยสำนักงานของภาควิชาวิทยาการคอมพิวเตอร์ตั้งอยู่ที่อาคารเรียนรวมทางวิทยาศาสตร์ (หลังเก่า) 2 ชั้น',2)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2538',2538,'ภาควิชาวิทยาการคอมพิวเตอร์ได้เปิดสอนหลักสูตรสาขาวิชาวิทยาการคอมพิวเตอร์ขึ้น เป็นสาขาวิชาแรกในคณะวิทยาศาสตร์ โดยมีนักศึกษาเข้าศึกษาเป็นรุ่นแรกจำนวน 38 คน พร้อมกับได้รับงบประมาณจัดซื้อเครื่องไมโครคอมพิวเตอร์คอมพิวเตอร์รุ่น486 เพิ่มอีกจำนวน 30 เครื่อง ต่อจากนั้นในแต่ละปีการศึกษาก็รับนักศึกษาเข้าใหม่อีกปีละประมาณ 50 คน',3)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2543',2543,'สาขาวิชาวิทยาการคอมพิวเตอร์ มีจำนวนนักศึกษาทั้ง 4 ชั้นปีประมาณ 200 คน และมีนักศึกษาที่สำเร็จการศึกษาจบตามหลักสูตร ออกไปรับใช้ประเทศชาติแล้วจำนวน 2 รุ่น ประมาณ 65 คน ขณะนั้นภาควิชาวิทยาการคอมพิวเตอร์ได้ย้ายสำนักงานมาอยู่ที่อาคารเรียนรวมทางวิทยาศาสตร์ (หลังใหม่) ชั้นที่ 6 โดยมีห้องปฏิบัติการคอมพิวเตอร์เบื้องต้นสำหรับนักศึกษาสาขาวิชาอื่น ๆ เพิ่มอีกจำนวน 2 ห้องปฏิบัติการ โดยติดตั้งระบบ LAN ที่ใช้เครื่องไมโครคอมพิวเตอร์ Pentium III 500 MHz ใช้ระบบปฏิบัติการ WINDOWS 98 จำนวน 50 เครื่อง ห้องปฏิบัติการคอมพิวเตอร์สำหรับนักศึกษาสาขาวิชาวิทยาการคอมพิวเตอร์ จำนวน 2 ห้อง โดยติดตั้งระบบ LAN ที่ใช้เครื่องไมโครคอมพิวเตอร์ Pentium III 500 MHz ระบบปฏิบัติการ WINDOWS NT จำนวน 100 เครื่อง ห้องปฏิบัติการคอมพิวเตอร์ระบบ UNIX สำหรับงานวิจัยของคณาจารย์และงานสำหรับทำโครงงาน คอมพิวเตอร์ของนักศึกษาสาขาวิชาวิทยาการคอมพิวเตอร์ชั้นปีที่ 4 ประกอบด้วยไมโครคอมพิวเตอร์ SUN จำนวน 5 เครื่อง เครื่องไมโครคอมพิวเตอร์ Silicon Graphic จำนวน 2 เครื่อง และเครื่องไมโครคอมพิวเตอร์ Pentium III 500 MHz จำนวน 3 เครื่อง',4)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2545',2545,'ภาควิชาวิทยาการคอมพิวเตอร์ เริ่มเปิดการเรียนการสอนหลักสูตรสาขาวิชาที่ 2 คือ หลักสูตรสาขาวิชาเทคโนโลยีสารสนเทศ สังกัดภาควิชาวิทยาการคอมพิวเตอร์ มีนักศึกษาภาคปกติ จำนวนประมาณ 55 คนและภาคสมทบ จำนวนประมาณ 90 คน ปีการศึกษา 2547 ภาควิชาวิทยาการคอมพิวเตอร์ ได้เพิ่มจำนวนห้องเรียนปฏิบัติการคอมพิวเตอร์ จำนวน 1 ห้องเรียน และห้องบรรยายคอมพิวเตอร์จำนวน 1 ห้องเรียน สำหรับใช้ในการเรียนการสอนของสาขาวิชาเทคโนโลยีสารสนเทศ โดยตั้งอยู่ที่อาคารเรียนรวมทางวิทยาศาสตร์ (หลังเก่า) 2 ชั้น และจัดซื้อเครื่องไมโครคอมพิวเตอร์ Intel รุ่น Pentium 4 ความเร็วขนาด 3.0 GHz จำนวน 20 เครื่อง',5)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2549',2549,'ภาควิชาวิทยาการคอมพิวเตอร์ รับอาจารย์มาเพิ่มจำนวน 2 คน และมีอาจารย์ที่ได้รับทุนการศึกษากลับมาปฏิบัติงานจำนวน 2 คน เพื่อรองรับรายวิชาของสาขาวิชาวิทยาการคอมพิวเตอร์และสาขาวิชาเทคโนโลยีสารสนเทศที่มีจำนวนรายวิชาเพิ่มมากขึ้น',6)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2550',2550,'ภาควิชาวิทยาการคอมพิวเตอร์ มีจำนวนนักศึกษาทั้ง 2 สาขาวิชา รวมทั้งหมด (ภาคปกติและภาคสมทบ) ประมาณ 433 คน คณาจารย์ 18 คน (รวมทั้งนักเรียนทุนโท-เอกและอาจารย์ ลาศึกษาต่อ)',7)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2551',2551,'ภาควิชาวิทยาการคอมพิวเตอร์ ยกเลิกภาควิชาเปลี่ยนแปลงเป็น สาขาวิชาวิทยาการคอมพิวเตอร์ แยกตัวออกจากสาขาวิชาเทคโนโลยีสารสนเทศ',8)
