INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2554',2554,'สาขาวิชาวิทยาการคอมพิวเตอร์ รับสมัครพนักงานมหาวิทยาลัยตำแหน่งอาจารย์วุฒิการศึกษาระดับปริญญาโท จำนวน 1 อัตรา',9)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO department_histories (id,department_id,period_label,academic_year,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'ปีการศึกษา 2555',2555,'สาขาวิชาวิทยาการคอมพิวเตอร์ มีห้องปฏิบัติการคอมพิวเตอร์ใหม่เพิ่มอีก จำนวน 1 ห้อง คือ ห้องปฏิบัติการคอมพิวเตอร์ 3203 ชั้น 2 อาคารจุฬาภรณ์ โดยได้จัดซื้อเครื่องไมโครคอมพิวเตอร์ Intel รุ่น Core i7 จำนวน 46 เครื่อง และมีห้องสำหรับวิจัยทางคอมพิวเตอร์ คือ ห้อง 3204 ชั้น 2 อาคารจุฬาภรณ์ และได้มีการบรรจุพนักงานมหาวิทยาลัยตำแหน่งอาจารย์ระดับปริญญาเอก จำนวน 1 คน สาขาวิชาได้มีโลโก้ของสาขาวิชาฯ โดยเป็นผลงานการออกแบบของนักศึกษาและทางสาขาวิชาฯได้ปรับปรุงสีให้เหมาะสมโดยใช้สีฟ้าเข้มเป็นสัญลักษณ์ของสาขาวิชาฯ สาขาวิชาวิทยาการคอมพิวเตอร์ มีจำนวนนักศึกษาที่กำลังศึกษา รวมทั้งหมดประมาณ 472 คน คณาจารย์ 14 คน (รวมทั้งนักเรียนทุนโท-เอกและอาจารย์ลาศึกษาต่อ)',10)
ON CONFLICT (department_id,period_label) DO UPDATE SET description_th=EXCLUDED.description_th, academic_year=EXCLUDED.academic_year, sort_order=EXCLUDED.sort_order, updated_at=now();

-- ===== หลักสูตร 2565 (มีอยู่แล้ว: 65304010) และ 2570 (ใหม่) =====
INSERT INTO curricula (id,code,department_id,name_th,name_en,curriculum_year,total_credits,national_code,degree_full_th,degree_short_th,degree_full_en,degree_short_en,study_duration_years,instruction_language,philosophy_th,significance_th,vision_th,mission_th)
VALUES (gen_random_uuid()::text,'65304010',(SELECT id FROM departments WHERE code = 'CS'),'หลักสูตรวิทยาศาสตรบัณฑิต สาขาวิชาวิทยาการคอมพิวเตอร์','Bachelor of Science Program in Computer Science',2565,120,'25490131103057','วิทยาศาสตรบัณฑิต (วิทยาการคอมพิวเตอร์)','วท.บ. (วิทยาการคอมพิวเตอร์)','Bachelor of Science (Computer Science)','B.Sc. (Computer Science)',4,'ภาษาไทย/ภาษาอังกฤษ','มุ่งเน้นการผลิตบัณฑิตให้มีความรู้ความสามารถทั้งในทางทฤษฎีและปฏิบัติ มีคุณธรรม จริยธรรม พร้อมปรับตัวเข้ากับเทคโนโลยีสมัยใหม่ เพื่อร่วมพัฒนาสังคมและประเทศชาติอย่างยั่งยืน','ในยุคแห่งการเปลี่ยนผ่านสู่ดิจิทัล (Digital Transformation) สาขาวิชาวิทยาการคอมพิวเตอร์ถือเป็นรากฐานสำคัญที่สุดในการขับเคลื่อนองค์กร เศรษฐกิจ และสังคม บัณฑิตมีความสำคัญในการคิดค้นระบบซอฟต์แวร์ การจัดการข้อมูล และการสร้างสรรค์นวัตกรรมดิจิทัลเพื่อยกระดับคุณภาพชีวิตของผู้คน','สร้างนวัตกรรมเทคโนโลยี มุ่งสู่ความเป็นเลิศทางวิชาการ และผลิตบัณฑิตนักปฏิบัติตอบโจทย์อุตสาหกรรมแห่งอนาคต','จัดการเรียนการสอน บริการวิชาการ บ่มเพาะทักษะวิจัยเชิงลึก และสร้างสรรค์นวัตกรรมซอฟต์แวร์ควบคู่คุณธรรมจริยธรรม')
ON CONFLICT (code) DO UPDATE SET name_th=EXCLUDED.name_th, name_en=EXCLUDED.name_en, curriculum_year=EXCLUDED.curriculum_year, total_credits=EXCLUDED.total_credits, national_code=EXCLUDED.national_code,
  degree_full_th=EXCLUDED.degree_full_th, degree_short_th=EXCLUDED.degree_short_th, degree_full_en=EXCLUDED.degree_full_en, degree_short_en=EXCLUDED.degree_short_en,
  study_duration_years=EXCLUDED.study_duration_years, instruction_language=EXCLUDED.instruction_language, philosophy_th=EXCLUDED.philosophy_th,
  significance_th=EXCLUDED.significance_th, vision_th=EXCLUDED.vision_th, mission_th=EXCLUDED.mission_th, updated_at=now();
INSERT INTO curricula (id,code,department_id,name_th,name_en,curriculum_year,total_credits,national_code,degree_full_th,degree_short_th,degree_full_en,degree_short_en,study_duration_years,instruction_language,philosophy_th,significance_th,vision_th,mission_th)
VALUES (gen_random_uuid()::text,'25700131103057',(SELECT id FROM departments WHERE code = 'CS'),'หลักสูตรวิทยาศาสตรบัณฑิต สาขาวิชาวิทยาการคอมพิวเตอร์','Bachelor of Science Program in Computer Science',2570,120,'25700131103057','วิทยาศาสตรบัณฑิต (วิทยาการคอมพิวเตอร์)','วท.บ. (วิทยาการคอมพิวเตอร์)','Bachelor of Science (Computer Science)','B.Sc. (Computer Science)',4,'ภาษาไทย/ภาษาอังกฤษ','มุ่งมั่นสร้างสรรค์นวัตกรรมดิจิทัล ปัญญาประดิษฐ์ และวิศวกรรมซอฟต์แวร์ล้ำสมัย ผลิตบัณฑิตนักปฏิบัติที่มีสมรรถนะระดับสากล ยึดมั่นในจรรยาบรรณวิชาชีพ และร่วมพัฒนาสังคมอย่างยั่งยืน','ในยุคแห่ง AI Universe และเทคโนโลยีล้ำสมัย (Emerging Technologies) วิทยาการคอมพิวเตอร์คือหัวใจหลักในการขับเคลื่อนโครงสร้างพื้นฐานดิจิทัล วิศวกรรมซอฟต์แวร์ขั้นสูง DevOps, Cloud Computing, Cybersecurity และ Data Governance เพื่อเตรียมความพร้อมให้องค์กรและสังคมก้าวทันโลกอนาคต','ยกระดับหลักสูตรสู่ศูนย์กลางความเป็นเลิศด้าน AI, วิศวกรรมซอฟต์แวร์ และโครงสร้างพื้นฐานดิจิทัลระดับสากล','บ่มเพาะทักษะวิศวกรรมซอฟต์แวร์ขั้นสูง AI & Big Data สื่อสารองค์ความรู้และสร้างผู้ประกอบการดิจิทัลยุคใหม่ที่มีจริยธรรม')
ON CONFLICT (code) DO UPDATE SET name_th=EXCLUDED.name_th, name_en=EXCLUDED.name_en, curriculum_year=EXCLUDED.curriculum_year, total_credits=EXCLUDED.total_credits, national_code=EXCLUDED.national_code,
  degree_full_th=EXCLUDED.degree_full_th, degree_short_th=EXCLUDED.degree_short_th, degree_full_en=EXCLUDED.degree_full_en, degree_short_en=EXCLUDED.degree_short_en,
  study_duration_years=EXCLUDED.study_duration_years, instruction_language=EXCLUDED.instruction_language, philosophy_th=EXCLUDED.philosophy_th,
  significance_th=EXCLUDED.significance_th, vision_th=EXCLUDED.vision_th, mission_th=EXCLUDED.mission_th, updated_at=now();

-- ===== วัตถุประสงค์ และ PLO =====
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'01','ด้านการผลิตบัณฑิต','เพื่อผลิตบัณฑิตที่มีความรู้ ความเชี่ยวชาญด้านวิทยาการคอมพิวเตอร์ มีทักษะการปฏิบัติงานจริง และสามารถประยุกต์ใช้เทคโนโลยีในการแก้ปัญหาได้อย่างมีประสิทธิภาพ',1)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'02','ด้านการวิจัยและนวัตกรรม','เพื่อส่งเสริมและสร้างสรรค์ผลงานวิจัย นวัตกรรมซอฟต์แวร์ เทคโนโลยีสารสนเทศ และปัญญาประดิษฐ์ที่มีคุณภาพตอบโจทย์ความต้องการของอุตสาหกรรม',2)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'03','ด้านบริการวิชาการ','เพื่อให้บริการทางวิชาการ ถ่ายทอดองค์ความรู้และเทคโนโลยีแก่คอมมูนิตี้ ชุมชนท้องถิ่น และองค์กรภายนอกเพื่อการพัฒนาอย่างยั่งยืน',3)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'04','ด้านคุณธรรมและจริยธรรม','เพื่อปลูกฝังคุณธรรม จริยธรรม จรรยาบรรณวิชาชีพ ความรับผิดชอบต่อหน้าที่ สังคม และสิ่งแวดล้อม',4)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'01','ด้านวิศวกรรมซอฟต์แวร์และ AI ล้ำสมัย','เพื่อผลิตบัณฑิตให้มีความเชี่ยวชาญระดับสูงด้านสถาปัตยกรรมซอฟต์แวร์ ปัญญาประดิษฐ์ การประมวลผลข้อมูล และโครงสร้างพื้นฐานดิจิทัล',5)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'02','ด้านนวัตกรรมและเทคโนโลยีอนาคต','เพื่อสร้างสรรค์นวัตกรรมดิจิทัล โซลูชันคลาวด์ การจัดการข้อมูลขนาดใหญ่ และระบบอัตโนมัติที่ตอบโจทย์ภาคอุตสาหกรรมยุคใหม่',6)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'03','ด้านการเป็นผู้ประกอบการและการเรียนรู้ตลอดชีวิต','เพื่อพัฒนาทักษะการสร้างสรรค์นวัตกรรม แนวคิดผู้ประกอบการดิจิทัล (Digital Entrepreneurship) และส่งเสริมการเรียนรู้ปรับตัวตลอดชีวิต',7)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_objectives (id,curriculum_id,code,title_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'04','ด้านธรรมาภิบาลข้อมูลและสิ่งแวดล้อมยั่งยืน','เพื่อปลูกฝังการตระหนักรู้ด้านผลกระทบของไอทีต่อสังคม สิ่งแวดล้อม ธรรมาภิบาลข้อมูล (Data Governance) และจรรยาบรรณวิชาชีพ',8)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'PLO1','การพัฒนาระบบและซอฟต์แวร์',NULL,'มีความรู้ความเข้าใจในหลักการทางวิทยาการคอมพิวเตอร์ สามารถออกแบบ พัฒนา ทดสอบ และประยุกต์ใช้ระบบซอฟต์แวร์ที่มีประสิทธิภาพสูง',9)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'PLO2','ปัญญาประดิษฐ์และวิทยาการข้อมูล',NULL,'สามารถประยุกต์ใช้เทคโนโลยีปัญญาประดิษฐ์ (AI) การเรียนรู้ของเครื่อง (Machine Learning) และการจัดการข้อมูลขนาดใหญ่ (Big Data Analytics)',10)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'PLO3','โครงสร้างพื้นฐานและความปลอดภัยคลาวด์',NULL,'เข้าใจการทำงานของระบบเครือข่าย สถาปัตยกรรมคลาวด์ (Cloud Computing) และการรักษาความมั่นคงปลอดภัยทางไซเบอร์',11)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '65304010'),'PLO4','ทักษะการทำงานร่วมกันและจรรยาบรรณวิชาชีพ',NULL,'มีทักษะการสื่อสาร ทำงานร่วมกับผู้อื่นเป็นทีม มีความคิดสร้างสรรค์ ปรับตัวต่อการเปลี่ยนแปลง และปฏิบัติตามจรรยาบรรณวิชาชีพ IT',12)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'PLO1','ความรับผิดชอบและความยั่งยืน','ความรับผิดชอบต่อสังคมและสิ่งแวดล้อมทางเทคโนโลยีสารสนเทศ','ประเมิน ผลกระทบของเทคโนโลยีสารสนเทศต่อสังคมและสิ่งแวดล้อมเพื่อการพัฒนาเทคโนโลยีที่มีความรับผิดชอบและยั่งยืน',13)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'PLO2','วิศวกรรมซอฟต์แวร์','วิศวกรรมซอฟต์แวร์และการแก้ปัญหาทางเทคนิคที่ซับซ้อน','ปฏิบัติการสร้าง ระบบซอฟต์แวร์และโปรแกรมเพื่อแก้ปัญหาทางเทคนิคที่ซับซ้อน ได้อย่างถูกต้อง แม่นยำ และสม่ำเสมอ โดยใช้หลักการวิศวกรรมซอฟต์แวร์ เทคโนโลยี และเครื่องมือที่เหมาะสม',14)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'PLO3','การสื่อสารองค์ความรู้','การสื่อสารองค์ความรู้ทางวิทยาการคอมพิวเตอร์อย่างมีประสิทธิภาพ','สื่อสาร องค์ความรู้และผลงานทางวิทยาการคอมพิวเตอร์ให้เหมาะสมกับกลุ่มเป้าหมายได้อย่างชำนาญและมีประสิทธิภาพ',15)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'PLO4','จรรยาบรรณวิชาชีพ','จรรยาบรรณวิชาชีพและความรับผิดชอบต่อผู้มีส่วนได้ส่วนเสีย','ยึดมั่น ในจรรยาบรรณวิชาชีพและความรับผิดชอบต่อผู้ใช้งาน องค์กรและวิชาชีพในการปฏิบัติงานด้านวิทยาการคอมพิวเตอร์',16)
ON CONFLICT (curriculum_id,code) DO UPDATE SET title_th=EXCLUDED.title_th, subtitle_th=EXCLUDED.subtitle_th, description_th=EXCLUDED.description_th, sort_order=EXCLUDED.sort_order, updated_at=now();
INSERT INTO curriculum_learning_outcomes (id,curriculum_id,code,title_th,subtitle_th,description_th,sort_order) VALUES (gen_random_uuid()::text,(SELECT id FROM curricula WHERE code = '25700131103057'),'PLO5','การเรียนรู้ตลอดชีวิต','การเรียนรู้ตลอดชีวิตและการทำงานร่วมกันแบบปรับตัว','ให้คุณค่า กับการเรียนรู้เทคโนโลยีใหม่ การปรับตัวต่อการเปลี่ยนแปลง และการทำงานร่วมกับผู้อื่น',17)
