INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-25','ทั่วไป','โครงการพัฒนาสมรรถนะด้าน (AI) ให้กับบุคลากร มหาวิทยาลัยแม่โจ้ หัวข้อ “การจัดทำเอกสารประกอบการสอนและตำราให้เข้าถึงผู้เรียนยุคใหม่”','ขอเชิญสายวิชาการเข้าร่วมโครงการพัฒนาสมรรถนะด้าน (AI) ให้กับบุคลากร มหาวิทยาลัยแม่โจ้ หัวข้อ “การจัดทำเอกสารประกอบการสอนและตำราให้เข้าถึงผู้เรียนยุคใหม่”','https://erp.mju.ac.th/hrDevelopmentRegister.aspx?ID=NTkwMDE=','https://csmju.com/files/articles/2026/08/1787643268206-3c39dd0c-1a3a-4c71-b1dd-9b8e4ec34207.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-25','ทั่วไป','ขอแสดงความยินดี กับบุคลากรหลักสูตรสาขาวิชาฯ ที่ได้รับรางวัลนักวิจัยดีเด่นคณะวิทยาศาสตร์ ม. แม่โจ้ เนื่องในงานมหากรรมวิทยาศาสตร์และเทคโนโลยี 2569','ขอแสดงความยินดี  กับ ผศ.ดร. ปวีณ  เขื่อนแก้ว 
ผศ.ดร.สมนึก สินธุปวน และ ผศ.ภานุวัฒน์ เมฆะ 
ที่ได้รับรางวัลนักวิจัยดีเด่นคณะวิทยาศาสตร์ ม. แม่โจ้ เนื่องในงานมหกรรมวิทยาศาสตร์และเทคโนโลยี 2569 เมื่อวันที่ 18 สิงหาคม 2569',NULL,'https://csmju.com/files/articles/2026/08/1787639491269-5f0fce54-9192-49e2-9f44-ce9c0082cb9e.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','โครงการ','บริษัท S3 Invent เข้ามาพูดคุยเพื่อสร้างความร่วมมือกับสาขาวิชา','รายละเอียดข่าว :
วันศุกรที่ 21 ต.ค. 2565 สาขาวิชาวิทยาการคอมพิวเตอร์ คณะวิทยาศาสตร์ มหาวิทยาลัยแม่โจ้ ขอขอบคุณบริษัท S3 Invent ที่ทำงานด้าน Digital/Data Science Consulting กับ Solution Provider และบริษัท TrueEye.AI ทำ AI ทางด้านการแพทย์ (http://www.trueeye.ai) ที่เข้ามาร่วมพูดคุย เพื่อสร้างความร่วมมือทางด้านวิชาการ วิจัย รวมถึงการฝึกงานและสหกิจศึกษาของนักศึกษาต่อไป',NULL,'https://csmju.com/files/articles/2026/08/1787119615413-35178922-0572-44e1-b450-330c20615e97.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','กิจกรรม','ขอเชิญชวนนักเรียนเข้าร่วมโครงการพัฒนาทักษะด้านเทคโนโลยีและนวัตกรรมแบบ AR (Augmented Reality) ระดับเบื้องต้นเพื่อเตรียมตัวเข้าสู่จักรวาลนฤมิต (Metaverse) สำหรับนักเรียน','รายละเอียดข่าว :
ขอเชิญชวนนักเรียนเข้าร่วมโครงการพัฒนาทักษะด้านเทคโนโลยีและนวัตกรรมแบบ AR (Augmented Reality) ระดับเบื้องต้นเพื่อเตรียมตัวเข้าสู่จักรวาลนฤมิต (Metaverse) สำหรับนักเรียน \r\nในวันที่ 18 พฤศจิกายน 2565 ณ ห้องปฏิบัติการคอมพิวเตอร์ ชั้น 6 อาคาร 60 ปี แม่โจ้ สาขาวิชาวิทยาการคอมพิวเตอร์ คณะวิทยาศาสตร์ มหาวิทยาลัยแม่โจ้ (แบบออนไซต์และแบบออนไลน์)\r\nhttps://docs.google.com/.../1FAIpQLSeq29scrtS.../viewform\r\nแบบออนไซต์ (On-site)\r\n- สำหรับนักเรียนที่มีความประสงค์อบรมแบบออนไซต์ ต้องเป็นนักเรียนระดับมัธยศึกษาตอนปลายเท่านั้น ถึงสามารถลงทะเบียนการอบรมแบบออนไซต์ได้ จำกัดจำนวนจากโรงเรียน ละไม่เกิน 5 คน โดยจำกัดจำนวนผู้อบรมทั้งหมดไม่เกิน 44 คนแรก โดยไม่ค่าใช้จ่ายใดๆ แต่ผู้เข้าร่วมอบรมจะต้องเดินทางมาอบรมเอง ณ ห้องปฏิบัติการคอมพิวเตอร์ ชั้น 6 อาคาร 60 ปี แม่โจ้ สาขาวิชาวิทยาการคอมพิวเตอร์ คณะวิทยาศาสตร์ มหาวิทยาลัยแม่โจ้\r\n(สำหรับผู้ที่ผ่านการอบรมแบบออนไซต์ จะได้รับใบประกาศนียบัตรและโควต้าเพื่อศึกษาต่อของสาขาวิชาฯ)\r\nแบบออนไลน์ (On-line)\r\n - สำหรับนักเรียนผู้สนใจทุกระดับชั้น (ประถมศึกษาหรือมัธยมศึกษา ทั้งตอนต้นและตอนปลาย) ที่มีความประสงค์จะอบรมแบบออนไลน์ หรือผู้ที่ลงทะเบียนอบรมแบบออนไซต์ไม่ทัน 44 คนแรก จะเป็นการอบรมแบบออนไลน์\r\n(สำหรับผู้ที่ผ่านการอบรมแบบออนไลน์ จะได้รับใบประกาศนียบัตรอิเล็กทรอนิกส์)\r\n*** หมายเหตุ สำหรับท่านที่ต้องการสอบถามข้อมูลเพิ่มเติมสามารถ เข้าร่วมโอเพนแชท ''โครงการพัฒนาทักษะด้านเทคโนโลยีและนวัตกรรม AR'' โปรดแตะลิงก์ด้านล่างนี้ https://line.me/ti/g2/zFIzJvoJxhpIw82OV8Uz3ZylYH-dr0nSr_xT1A?utm_source=invitation&utm_medium=link_copy&utm_campaign=default&fbclid=IwAR2xMeDsTfO3wHRp6lC6SZyWOtpWKmrNf7ADU2PxbOid4xqachFN1cLxSuI',NULL,'https://csmju.com/files/articles/2026/08/1787119580077-7820d777-a282-48a2-8bfa-c26c5f4e1824.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','โครงการ','โครงการพัฒนาทักษะด้านเทคโนโลยีและนวัตกรรมแบบ AR (Augmented Reality) ระดับเบื้องต้นเพื่อเตรียมตัวเข้าสู่จักรวาลนฤมิต (Metaverse) สำหรับนักเรียน','รายละเอียดข่าว :
โครงการพัฒนาทักษะด้านเทคโนโลยีและนวัตกรรมแบบ AR (Augmented Reality) ระดับเบื้องต้นเพื่อเตรียมตัวเข้าสู่จักรวาลนฤมิต (Metaverse) สำหรับนักเรียน จัดเมื่อวันที่ 18 พ.ย.65 ณ ห้องปฏิบัติการคอมพิวเตอร์ชั้น6 โดยมีนักเรียนระดับ ม.ปลาย เข้าร่วมอบรมทั้งรูปแบบออนไซต์และออนไลน์ รวมทั้งหมด 81 คน รวม 21 โรงเรียน โดยมีวัตถุประสงค์เพื่อส่งเสริมนักเรียนให้มีทักษะความรู้ด้านการใช้โปรแกรม Spark AR Studio และโปรแกรมอื่น ๆ ที่เกี่ยวข้องได้อย่างมีประสิทธิภาพ เสริมสร้างนักเรียนให้เกิดความคิดริเริ่มสร้างสรรค์เกิดทักษะออกแบบและพัฒนาสื่อเชิงโต้ตอบโดยใช้เทคโนโลยี AR ระดับเบื้องต้นได้ นักเรียนสามารถนำความรู้ที่ได้ไปสร้างสรรค์ผลงานหรือนวัตกรรมด้าน AR ระดับเบื้องต้นได้ นอกจากนั้นยังมีการประชาสัมพันธ์รับนักศึกษาใหม่เข้าศึกษาต่อในมหาวิทยาลัย ปีการศึกษา2566 รูปเพิ่มเติมได้ที่ : https://photos.app.goo.gl/bxszzM13LED9SyrC8',NULL,'https://csmju.com/files/articles/2026/08/1787119536426-fd6c66f9-41d5-401d-9719-c8fe1b626001.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','โครงการ','ตัวแทนบริษัทไอเน็ต แมเนจด์เซอร์วิสเซส จำกัด เข้ามาหารือร่วมกับคณาจารย์สาขาวิชาวิทยาการคอมพิวเตอร์','รายละเอียดข่าว :
วันที่ 7 ธันวาคม 2565 เวลา 13.00 น. ตัวแทนบริษัทไอเน็ต แมเนจด์เซอร์วิสเซส จำกัด เข้ามาหารือร่วมกับคณาจารย์สาขาวิชาวิทยาการคอมพิวเตอร์ เพื่อจัดอบรมเนื้อหาและเทคโนโลยีใหม่ๆ ทางด้านระบบเครือข่ายและการพัฒนาโปรแกรมด้านเครือข่าย เสริมความรู้ให้แก่นักศึกษาชั้นปีที่3-4 \r\nในรายวิชา คพ 433 เครือข่ายคอมพิวเตอร์ คพ434 การเขียนโปรแกรมเครือข่าย และ คพ 492 สัมมนา ที่เปิดสอนภาคเรียนที่ 2 ปีการศึกษา 2565',NULL,'https://csmju.com/files/articles/2026/08/1787119488694-f92d25cc-8e49-4f82-844e-646a5425a4ff.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','โครงการ','สาขาวิชาวิทยาการคอมพิวเตอร์และชมรมคอมพิวเตอร์ จัดโครงการอบรมเชิงปฏิบัติการค่ายยุวชนคอมพิวเตอร์ ครั้งที่ 21','รายละเอียดข่าว :
ระหว่างวันที่ 2-4 กุมภาพันธ์ 2566 สาขาวิชาวิทยาการคอมพิวเตอร์และชมรมคอมพิวเตอร์ จัดโครงการอบรมเชิงปฏิบัติการค่ายยุวชนคอมพิวเตอร์ ครั้งที่ 21 ในหัวข้อเรื่อง ''อินเทอร์เน็ตทุกสรรพสิ่ง (IOT : Internet of Things) และการนำเสนอข้อมูลด้วยภาพ (Data Visualization)'' ให้กับน้องๆ นักเรียนจำนวน 45 คน ทั้งหมด 18 โรงเรียน ณ อาคาร 60 ปี แม่โจ้ และอาคารจุฬาภรณ์ คณะวิทยาศาสตร์ มหาวิทยาลัยแม่โจ้ โดยมีวัตถุประสงค์เพื่อเสริมสร้างความรู้ด้านคอมพิวเตอร์และนวัตกรรมเทคโนโลยีสารสนเทศ พร้อมทั้งพัฒนาด้านคุณธรรม จริยธรรมและเน้นความสามัคคี ประชาสัมพันธ์พร้อมกับแนะแนวทางการศึกษา ให้แก่นักเรียนชั้นมัธยมศึกษาตอนปลาย ซึ่งเป็นเยาวชนที่อยู่ในวัยศึกษาและกำลังก้าวเข้าสู่การเรีย นในระดับอุดมศึกษา อันจะส่งผลให้เป็นการส่งเสริมให้มีผู้สนใจจะเข้าศึกษาในสาขาวิชาวิทยาการคอมพิวเตอร์เพิ่มมากยิ่งขึ้น และเป็นกำลังสำคัญของชาติต่อไป',NULL,'https://csmju.com/files/articles/2026/08/1787119428062-0a75da5a-8b36-49fe-8ffd-c3220abc9459.jpg')
ON CONFLICT (department_id,published_on,title) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content, external_url=EXCLUDED.external_url, image_url=EXCLUDED.image_url, updated_at=now();
INSERT INTO news_articles (id,department_id,published_on,category,title,content,external_url,image_url) VALUES (gen_random_uuid()::text,(SELECT id FROM departments WHERE code = 'CS'),'2026-08-19','กิจกรรม','บุคลากรและนักศึกษาหลักสูตรสาขาวิชาวิทยาการคอมพิวเตอร์ ร่วมทำกิจกรรม Big Cleaning day','รายละเอียดข่าว :
เนื่องในวันสิ่งแวดล้อมโลก วันที่ 5 มิถุนายน 2566 🌏🌏 คณะวิทยาศาสตร์ มหาวิทยาลัยแม่โจ้ วันที่ 2 มิถุนายน 2566 บุคลากรและนักศึกษาหลักสูตรสาขาวิชาวิทยาการคอมพิวเตอร์ ร่วมทำกิจกรรม Big Cleaning day 🌿🌿 ทำความสะอาดห้องทำงาน ห้องเรียนของหลักสูตร',NULL,'https://csmju.com/files/articles/2026/08/1787119353011-9cb08c56-5efe-46ec-8b56-255597ce76fd.jpg')
